package com.bugtrace.backend;

import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;

class ControlledScenarioReportTest {
    final JsonMapper json=JsonMapper.builder().build();
    String report(String scenario,List<Integer> counts){int errors=(int)counts.stream().filter(n->n==-1).count(),dups=(int)counts.stream().filter(n->n>1).count();return ControlledScenarioReport.PREFIX+json.writeValueAsString(Map.of("scenario",scenario,"repetitions",counts.size(),"completed",counts.size()-errors,"duplicates",dups,"passes",counts.size()-errors-dups,"errors",errors,"clientTimeouts",scenario.equals("DELAYED_RESPONSE")?counts.size()-errors:0,"chargeCounts",counts));}
    Map<String,Object> metadata(int duplicates){var result=new LinkedHashMap<String,Object>();result.put("classification",duplicates>0?"ASSERTION_FAILED":"PASSED");result.put("snapshotVerifiedAfter",true);result.put("generatedTest",Map.of("installedSourceSha256","hash","unchangedAfterRun",true));result.put("stages",List.of(Map.of("goals",List.of("test-compile"),"exitCode",0)));result.put("junit",Map.of("tests",1,"failures",duplicates>0?1:0,"errors",0,"skipped",0,"details",duplicates>0?List.of(Map.of("className",GeneratedReproduction.SELECTOR,"testName","duplicateChargeOnRetry","type","org.opentest4j.AssertionFailedError","message","BUGTRACE_SCENARIO_DUPLICATES ==> expected: <0> but was: <"+duplicates+">")):List.of()));return result;}
    @Test void computesFailureRateFromValidTrials(){var summary=ControlledScenarioReport.parse(report("RETRY_AFTER_COMPLETION",List.of(2,1,2,-1)),"RETRY_AFTER_COMPLETION",4);assertEquals(3,summary.completed());assertEquals(2.0/3,summary.duplicateRate(),1e-9);assertEquals(1,summary.errors());assertTrue(summary.interpretation().contains("INCONCLUSIVE"));}
    @Test void zeroFailuresDoNotProveAbsence(){var summary=ControlledScenarioReport.parse(report("RETRY_AFTER_COMPLETION",Collections.nCopies(20,1)),"RETRY_AFTER_COMPLETION",20);assertEquals(0.0,summary.duplicateRate());assertTrue(summary.wilson95Upper()>0.1);assertTrue(summary.interpretation().contains("do not prove absence"));}
    @Test void delayedScenarioRequiresObservedClientTimeouts(){String valid=report("DELAYED_RESPONSE",List.of(2,2));assertEquals(2,ControlledScenarioReport.parse(valid,"DELAYED_RESPONSE",2).clientTimeouts());assertThrows(Exception.class,()->ControlledScenarioReport.parse(valid.replace("\"clientTimeouts\":2","\"clientTimeouts\":0"),"DELAYED_RESPONSE",2));}
    @Test void rejectsMissingOrDuplicateReports(){String line=report("CONCURRENT_RETRIES",List.of(3,3));assertThrows(Exception.class,()->ControlledScenarioReport.parse("", "CONCURRENT_RETRIES",2));assertThrows(Exception.class,()->ControlledScenarioReport.parse(line+"\n"+line,"CONCURRENT_RETRIES",2));}
    @Test void rejectsDifferentScenarioAndCount(){String line=report("CONCURRENT_RETRIES",List.of(3,3));assertThrows(Exception.class,()->ControlledScenarioReport.parse(line,"DELAYED_RESPONSE",2));assertThrows(Exception.class,()->ControlledScenarioReport.parse(line,"CONCURRENT_RETRIES",20));}
    @Test void rejectsInconsistentTotals(){String line=report("CONCURRENT_RETRIES",List.of(3,3));assertThrows(Exception.class,()->ControlledScenarioReport.parse(line.replace("\"duplicates\":2","\"duplicates\":0"),"CONCURRENT_RETRIES",2));}
    @Test void specificActualAssertionEstablishesObservedFailure(){var result=ControlledScenarioReport.evaluate(json.valueToTree(metadata(2)),report("CONCURRENT_RETRIES",List.of(3,3)),"hash","CONCURRENT_RETRIES",2);assertEquals("EXPECTED_FAILURE_OBSERVED",result.outcome());}
    @Test void passingBatchIsOnlyNotReproduced(){assertEquals("NOT_REPRODUCED",ControlledScenarioReport.evaluate(json.valueToTree(metadata(0)),report("RETRY_AFTER_COMPLETION",List.of(1,1)),"hash","RETRY_AFTER_COMPLETION",2).outcome());}
    @Test void setupErrorsAreNotSuccessfulReproduction(){assertEquals("UNEXPECTED_FAILURE",ControlledScenarioReport.evaluate(json.valueToTree(metadata(1)),report("RETRY_AFTER_COMPLETION",List.of(2,-1)),"hash","RETRY_AFTER_COMPLETION",2).outcome());}
    @Test void wrongSourceOrGenericFailureIsInsufficient(){String line=report("CONCURRENT_RETRIES",List.of(3,3));assertEquals("INFRASTRUCTURE_ERROR",ControlledScenarioReport.evaluate(json.valueToTree(metadata(2)),line,"other","CONCURRENT_RETRIES",2).outcome());var data=metadata(2);data.put("classification","INFRASTRUCTURE_ERROR");assertEquals("UNEXPECTED_FAILURE",ControlledScenarioReport.evaluate(json.valueToTree(data),line,"hash","CONCURRENT_RETRIES",2).outcome());}
}
